/**
 * Backup frequency & retention TIERS — the single source of truth for what each
 * backup tier grants (retention count, cadence) and its customer-facing copy.
 *
 * PURE module (no db, no settings imports) for the same reason as lib/extra-disk.ts:
 * the exact same maths is imported by the CLIENT wizard/upsell card that DISPLAYS a
 * price and by the server action / worker that ENFORCES + CHARGES it, so whatever
 * the customer sees is byte-for-byte what gets charged. Price resolution (the admin
 * setting) lives in the server-only lib/backup-upgrade.ts, mirroring how
 * extra-disk's pure maths sits apart from disk-expand's getSettingInt reader.
 *
 * MVP scope: only FREE (included, keep 2, daily) and PLUS (paid, keep 7, daily) are
 * SELLABLE. PRO/PREMIUM are defined for forward-compatibility but NOT offered in the
 * funnel — selling them needs pricing + (Premium) off-node storage this slice omits.
 * The MVP keeps cadence DAILY for every tier; only retention is sold.
 */

export type BackupTier = "FREE" | "PLUS" | "PRO" | "PREMIUM";

/** Legacy hardcoded retention every VPS shipped with (was worker CUSTOMER_BACKUP_KEEP=2). */
export const BACKUP_FREE_KEEP = 2;
/** Plus retention: a full week of daily restore points. */
export const BACKUP_PLUS_KEEP = 7;

/** Fallback Plus price when the `backup_plus_price_cents` admin setting is unset: $2.99/mo. */
export const BACKUP_PLUS_DEFAULT_PRICE_CENTS = 299;

/** Baseline cadence — daily. The MVP keeps every tier daily; only retention is sold. */
export const BACKUP_DAILY_INTERVAL_HOURS = 24;

/** Tiers a customer can actually pick in the MVP funnel. */
export const SELLABLE_BACKUP_TIERS: BackupTier[] = ["FREE", "PLUS"];

export type BackupTierSpec = {
  tier: BackupTier;
  /** Retention: how many recent archives are kept before the oldest are pruned. */
  keep: number;
  /** Scheduled cadence in hours. Daily across the board in the MVP. */
  intervalHours: number;
  /** Off-node/offsite durable copy. Always false in the MVP (Premium-only, deferred). */
  offsite: boolean;
  /** Short customer-facing name. */
  label: string;
  /** One-line description of what the tier keeps. */
  blurb: string;
  /** Whether this tier is offered in the funnel today. */
  sellable: boolean;
};

/** The tier -> {keep, cadence, offsite, copy} mapping. The ONE place this is defined. */
export function backupTierSpec(tier: BackupTier): BackupTierSpec {
  switch (tier) {
    case "PLUS":
      return {
        tier,
        keep: BACKUP_PLUS_KEEP,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: false,
        label: "Plus",
        blurb: `Keep the last ${BACKUP_PLUS_KEEP} daily backups — a full week of restore points.`,
        sellable: true,
      };
    case "PRO":
      return {
        tier,
        keep: 14,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: false,
        label: "Pro",
        blurb: "Keep two weeks of daily restore points.",
        sellable: false,
      };
    case "PREMIUM":
      return {
        tier,
        keep: 30,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: true,
        label: "Premium",
        blurb: "Keep a month of restore points with an off-node copy.",
        sellable: false,
      };
    case "FREE":
    default:
      return {
        tier: "FREE",
        keep: BACKUP_FREE_KEEP,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: false,
        label: "Standard",
        blurb: `Keep the last ${BACKUP_FREE_KEEP} daily backups. Included free.`,
        sellable: true,
      };
  }
}

/** Coerce arbitrary input (form value / round-tripped JSON) to a known tier; unknown => FREE. */
export function normalizeBackupTier(v: unknown): BackupTier {
  return v === "PLUS" || v === "PRO" || v === "PREMIUM" ? v : "FREE";
}

/**
 * The retention count the worker enforces for a row: an explicit per-row override
 * (`backupKeep`) wins, else the tier default. The single definition the VPS backup
 * executor's prune step reads.
 */
export function resolveBackupKeep(tier: BackupTier, keepOverride: number | null | undefined): number {
  if (keepOverride != null && keepOverride > 0) return Math.round(keepOverride);
  return backupTierSpec(tier).keep;
}

/**
 * Monthly price (integer cents) of a tier given the admin-tunable Plus price. PURE
 * so the wizard preview, the order charge and the renewal charge all derive the
 * SAME number (the display===charge invariant). Only PLUS is paid in the MVP; every
 * other tier is $0 here (PRO/PREMIUM are not sold, FREE is included).
 */
export function backupTierMonthlyCents(tier: BackupTier, plusCents: number): number {
  const p = Math.max(0, Math.round(plusCents));
  return tier === "PLUS" ? p : 0;
}

