 *   vzdump-qemu-102-2026_08_04-04_40_22.vma.zst -> 102
 */
function vmidFromArchive(file: string): number | null {
  const m = /^vzdump-[a-z]+-(\d+)-.*\.vma(\.(zst|gz|lzo))?$/i.exec(file);
  if (!m) return null;
  const n = Number(m[1]);
  return Number.isInteger(n) ? n : null;
}

/**
 * Read the whole-system backup status + dumpdir contents. Never throws — a
 * missing directory or unreadable file degrades to `missing`/`available:false`,
 * because the honest answer to "we cannot read the backup state" is to say so,
 * not to claim success (the exact failure mode scripts/backup-offsite.sh exists
 * to prevent).
 */
export async function readPlatformBackups(now = Date.now()): Promise<PlatformBackupsView> {
  const [vm, host, offsite, verify] = await Promise.all([
    readStatusFile("vm-backup.json"),
    readStatusFile("host-config.json"),
    readStatusFile("offsite.json"),
    readStatusFile("verify-restore.json"),
  ]);

  const subsystems: SubsystemStatus[] = [];

  const push = (
    key: SubsystemStatus["key"],
    label: string,
    s: Record<string, unknown> | null,
    detail: (s: Record<string, unknown>) => string
  ) => {
    if (!s) {
      subsystems.push({ key, label, ok: null, at: null, ageMs: null, detail: "no status file yet", missing: true });
      return;
    }
    subsystems.push({
      key,
      label,
      ok: typeof s.ok === "boolean" ? (s.ok as boolean) : null,
      at: typeof s.at === "string" ? (s.at as string) : null,
      ageMs: ageOf(s.at, now),
      detail: detail(s),
      missing: false,
    });
  };

  push("vm", "Whole-system VM backup", vm, (s) => {
    const mode = str(s.mode);
    const dest = str(s.dest);
    const keep = str(s.keepLast);
    if (s.ok === false) return `FAILED — ${str(s.error) || "see journalctl -u nxeon-backup-vms"}`;
    return `${mode || "dumpdir"} → ${dest || PLATFORM_DIR}${keep ? ` · keep-last ${keep}` : ""}`;
  });
  push("host-config", "Host configuration (/etc/pve)", host, (s) => {
    if (s.ok === false) return `FAILED — ${str(s.error) || "unknown"}`;
    const defs = str(s.vmDefinitions);
    return defs ? `${defs} VM definition(s) captured` : "captured";
  });
  push("offsite", "Off-site replication", offsite, (s) => {
    if (s.configured === false) return "NOT CONFIGURED — every backup lives only on this chassis";
    if (s.ok === false) return `FAILED — ${str(s.detail) || "replication failed"}`;
    return str(s.detail) || `replicated via ${str(s.kind) || "remote"}`;
  });
  push("verify-restore", "Restore verification", verify, (s) => {
    if (s.ok === false) return `FAILED — ${str(s.error) || "verification failed"}`;
    const arch = str(s.vmArchives);
    const warn = str(s.warnings);
    return `${arch ? `${arch} VM archive(s) verified` : "verified"}${warn ? ` · ${warn}` : ""}`;
  });

  // Dumpdir contents → newest archive per guest vmid.
  const guestsMap = new Map<number, PlatformGuest>();
  let totalArchives = 0;
  let totalBytes = 0;
  let dirReadable = false;
  try {
    const files = await fs.readdir(PLATFORM_DIR);
    dirReadable = true;
    for (const file of files) {
      const vmid = vmidFromArchive(file);
      if (vmid === null) continue;
      let mtimeMs = 0;
      let size = 0;
      try {
        const st = await fs.stat(path.join(PLATFORM_DIR, file));
        mtimeMs = st.mtimeMs;
        size = st.size;
      } catch {
        continue;
      }
      totalArchives++;
      totalBytes += size;
      const age = Math.max(0, now - mtimeMs);
      const cur = guestsMap.get(vmid);
      if (!cur) {
