import { fmtAge } from "@/lib/monitoring";
import type { PlatformBackupsView } from "@/lib/platform-backups";

/**
 * Whole-system ("platform") backup panel for /admin/backups.
 *
 * Renders the disaster-recovery backup state that the Proxmox-storage view is
 * structurally blind to (see lib/platform-backups.ts): the daily whole-system
 * VM dump, the /etc/pve host-config archive, off-site replication and restore
 * verification, plus the per-guest DR archives held in the dumpdir. Server
 * component, read-only.
 */
function ageLabel(ms: number | null): string {
  return ms === null ? "—" : fmtAge(ms);
}

function toneFor(ok: boolean | null): "green" | "red" | "slate" {
  if (ok === true) return "green";
  if (ok === false) return "red";
  return "slate";
}

// A subsystem is "stale" (worth an amber nudge) if its last successful run is
// older than ~28h — the daily units should always have run inside a day.
const STALE_MS = 28 * 60 * 60 * 1000;

export function PlatformBackupsPanel({ view }: { view: PlatformBackupsView }) {
  if (!view.available) {
    return (
      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
        <p className="text-sm font-semibold text-amber-300">
          Platform backup status is unreadable
        </p>
        <p className="mt-1 text-xs text-slate-400">
