47	/** Human-sized bytes for notification/log copy. */
48	export function humanBytes(n: number): string {
49	  if (!Number.isFinite(n) || n < 0) return "unknown size";
50	  const units = ["B", "KB", "MB", "GB", "TB"];
51	  let v = n;
52	  let i = 0;
53	  while (v >= 1024 && i < units.length - 1) {
54	    v /= 1024;
55	    i++;
56	  }
57	  return `${i === 0 ? v : v.toFixed(1)} ${units[i]}`;
58	}
