60	/**
61	 * Did THIS run demonstrably write a backup?
62	 *
63	 * Evidence is a volid present in `after` that was absent from `before`, carrying
64	 * a non-zero size. Set membership rather than a timestamp comparison on purpose:
65	 * `ctime` comes off the hypervisor and any window we computed would come off the
66	 * worker's clock, and skew between the two is exactly the kind of thing that
67	 * turns a proof back into a guess. A volid that was not there and now is cannot
68	 * be explained away by a clock.
69	 *
70	 * Every failure returns the reason AND the command an operator can run, because
71	 * "backup failed" with no next step is barely better than the silence it
72	 * replaced.
73	 */
74	export function freshBackupProof(opts: {
75	  vmid: number;
76	  before: readonly BackupArchive[];
77	  after: readonly BackupArchive[];
78	}): BackupProof {
79	  const { vmid } = opts;
80	  const check = `Check it yourself with: pvesm list backup --vmid ${vmid}`;
81	  const seen = new Set<string>();
82	  for (const b of opts.before) {
83	    if (b.vmid === vmid && typeof b.volid === "string") seen.add(b.volid);
84	  }
85	
86	  const fresh = opts.after.filter(
87	    (b) => b.vmid === vmid && typeof b.volid === "string" && !seen.has(b.volid)
88	  );
89	
90	  if (fresh.length === 0) {
