95	        `"backup" storage, so nothing was written and there is no restore point from this run. ` +
96	        check,
97	    };
98	  }
99	
100	  // Prefer the largest new archive: if a run somehow left a truncated stub beside
101	  // a good one, the good one is the honest answer.
102	  const sized = fresh
103	    .filter((b) => typeof b.size === "number" && Number.isFinite(b.size))
104	    .sort((a, b) => (b.size ?? 0) - (a.size ?? 0));
105	
106	  if (sized.length === 0) {
107	    return {
108	      proven: false,
109	      reason:
