120	      proven: false,
121	      reason:
122	        `a new archive for VMID ${vmid} appeared (${best.volid}) but it is 0 bytes — ` +
123	        `an empty file is not a backup and would fail at restore time. ` +
124	        check,
125	    };
126	  }
127	
128	  return { proven: true, volid: best.volid!, sizeBytes: best.size! };
129	}
