175	  autoBackup: boolean;
176	  intervalHours: number | null;
177	  lastVerifiedAt: Date | null;
178	  lastAttempt: { at: Date; status: string } | null;
179	}): BackupHealth {
180	  const hours = opts.intervalHours ?? 0;
181	  if (!opts.autoBackup || !(hours > 0)) {
182	    return { state: "off", detail: "Scheduled backups are off for this server." };
183	  }
184	
185	  const verified = opts.lastVerifiedAt;
