/**
 * Off-site (Mega) retention — pure decision logic for what to prune from the
 * Mega copy of the platform's backups.
 *
 * WHY THIS EXISTS
 * ----------------
 * `scripts/backup-offsite.sh` mirrors `/tank/backup/{db,platform}` to a Mega
 * account via `megatools megacopy`. megacopy's own contract (see its manpage)
 * is explicit: "no files are ever overwritten or removed" — it is upload-only.
 * That is the right default for a tool that also does one-way *downloads*, but
 * it means Mega storage grows forever unless something else prunes it, even
 * though the LOCAL copies these files came from already rotate out on a
 * schedule (`scripts/backup-db.sh` deletes dumps past `NXEON_DB_RETENTION_DAYS`
 * (14d default); `scripts/backup-vms.sh` / `backup-pve-config.sh` keep only the
 * newest `NXEON_*_BACKUP_KEEP` archives (3 by default)).
 *
 * The two rclone/rsync targets `backup-offsite.sh` already supports don't have
 * this problem: `rclone sync` and `rsync --delete` both mirror the destination
 * to exactly match the source, so a file pruned locally is pruned remotely on
 * the very next run for free. Mega is the odd one out, so it needs an explicit
 * prune step — this module IS that step's decision logic, kept dependency-free
 * (no fs, no child_process, no clock — `now` is always passed in) so it can be
 * unit tested without a Mega account, a filesystem, or `megatools` installed.
 *
 * TWO RULES, applied together:
 *
 *  1. MIRROR: delete any remote file whose name is no longer present in the
 *     local source directory. This is the primary mechanism — it makes the
 *     Mega copy track whatever the LOCAL retention policy already decided,
 *     exactly like the rclone/rsync paths do implicitly. No day-count guessing
 *     needed; it just follows local truth.
 *  2. AGE CAP: delete any remote file older than `maxAgeDays`, regardless of
 *     local state. This is a defence-in-depth backstop for the case the mirror
 *     rule can't reach — e.g. `OFFSITE_INCLUDE_VMS` was flipped off after
 *     having been on for a while, so the VM archives it already shipped are no
 *     longer represented by anything in the local source directory the next
 *     run even looks at, and would otherwise never be revisited.
 *
 * `scripts/backup-offsite.sh` currently wires up rule 1 only (it has no
 * reliable way to get parsed per-file timestamps out of `megals` without a live
 * account to verify the exact output format against — see the script's MEGA
 * section comment). Rule 2 is implemented and tested here so the policy is
 * defined precisely and ready to wire in once that's verified live.
 */

/** One file as it exists in Mega right now. */
export type RemoteFile = {
  name: string;
  /** Last-modified time, epoch ms. */
  mtimeMs: number;
};

/**
 * Default retention window for the Mega copy, in days.
 *
 * ASSUMPTION (flagged — could not be verified without real Mega credentials):
 * chosen to match the local PREMIUM backup tier's "keep a month" precedent
 * (see `lib/backup-tiers.ts` PREMIUM = keep 30 daily archives), which is also
 * comfortably inside Mega's smallest paid tier (Mega Pro Lite, 2TB as of this
 * writing) for this platform's current backup volume (~183GB in
 * /tank/backup at time of writing per `df -h /tank/backup`). If the Mega
 * account in use is a free 20GB account, or the platform's backup volume grows
 * materially, this default should be revisited — it is a policy knob, not a
 * hard limit enforced anywhere else.
 */
export const MEGA_OFFSITE_RETENTION_DAYS = 30;

export type MegaRetentionPlan = {
  /** Remote names to keep (present locally and inside the age cap). */
  keep: string[];
  /** Remote names to delete because no local file of that name exists. */
  deleteOrphaned: string[];
  /** Remote names to delete because they exceeded the age cap (rule 2). */
  deleteExpired: string[];
};

/**
 * Compute what should be deleted from the Mega copy of ONE label directory
 * (e.g. "db", "host-config", "vms" — see backup-offsite.sh's `sync_one`).
 *
 * `localNames` is every file basename currently in the local source dir for
 * this label (what megacopy would upload from, right now). `remoteFiles` is
 * everything megatools reports it holds for this label. A name that is both
 * local and inside the age cap is kept; everything else is deleted, orphaned
 * names taking priority in the return shape (a name can only match one rule —
 * dedup below picks orphaned first since "no longer wanted locally" is the
 * stronger signal than "old but still the current file").
 */
export function megaRetentionPlan(opts: {
  localNames: readonly string[];
  remoteFiles: readonly RemoteFile[];
  now: number;
  maxAgeDays?: number;
}): MegaRetentionPlan {
  const maxAgeDays = opts.maxAgeDays ?? MEGA_OFFSITE_RETENTION_DAYS;
  const maxAgeMs = Math.max(0, maxAgeDays) * 24 * 60 * 60 * 1000;
  const localSet = new Set(opts.localNames);

  const keep: string[] = [];
  const deleteOrphaned: string[] = [];
  const deleteExpired: string[] = [];

  for (const f of opts.remoteFiles) {
    if (!localSet.has(f.name)) {
      deleteOrphaned.push(f.name);
      continue;
    }
    const ageMs = opts.now - f.mtimeMs;
    if (ageMs > maxAgeMs) {
      deleteExpired.push(f.name);
      continue;
    }
    keep.push(f.name);
  }

  return { keep, deleteOrphaned, deleteExpired };
}

/** Convenience: every name a plan says to delete, orphaned first. */
export function namesToDelete(plan: MegaRetentionPlan): string[] {
  return [...plan.deleteOrphaned, ...plan.deleteExpired];
}

