} from "../lib/offsite-retention.ts";

const DAY = 24 * 60 * 60 * 1000;
const NOW = Date.parse("2026-08-26T12:00:00Z");

test("megaRetentionPlan keeps a file that is both local and within the age cap", () => {
  const plan = megaRetentionPlan({
    localNames: ["nxeon-20260826-030000.sql.gz"],
    remoteFiles: [{ name: "nxeon-20260826-030000.sql.gz", mtimeMs: NOW - 1 * DAY }],
    now: NOW,
  });
  assert.deepEqual(plan.keep, ["nxeon-20260826-030000.sql.gz"]);
  assert.deepEqual(plan.deleteOrphaned, []);
  assert.deepEqual(plan.deleteExpired, []);
});

test("megaRetentionPlan deletes remote files no longer present locally (mirror rule)", () => {
  // Local retention already pruned this dump; the remote copy should follow.
  const plan = megaRetentionPlan({
    localNames: ["nxeon-20260825-030000.sql.gz"],
    remoteFiles: [
      { name: "nxeon-20260825-030000.sql.gz", mtimeMs: NOW - 1 * DAY },
      { name: "nxeon-20260801-030000.sql.gz", mtimeMs: NOW - 25 * DAY }, // rotated out locally
    ],
    now: NOW,
  });
  assert.deepEqual(plan.keep, ["nxeon-20260825-030000.sql.gz"]);
  assert.deepEqual(plan.deleteOrphaned, ["nxeon-20260801-030000.sql.gz"]);
  assert.deepEqual(plan.deleteExpired, []);
});

test("megaRetentionPlan deletes remote files past the age cap even if still local", () => {
  // Defence-in-depth: still present locally, but older than the cap.
  const plan = megaRetentionPlan({
    localNames: ["host-config-20260101-000000.tar.gz"],
    remoteFiles: [
      { name: "host-config-20260101-000000.tar.gz", mtimeMs: NOW - 40 * DAY },
    ],
    now: NOW,
    maxAgeDays: 30,
  });
  assert.deepEqual(plan.keep, []);
  assert.deepEqual(plan.deleteExpired, ["host-config-20260101-000000.tar.gz"]);
  assert.deepEqual(plan.deleteOrphaned, []);
});

test("megaRetentionPlan: orphaned takes priority over expired for the same name", () => {
  // A name can't be in both buckets — orphaned (no longer wanted locally) wins.
  const plan = megaRetentionPlan({
    localNames: [],
    remoteFiles: [{ name: "stale.tar.gz", mtimeMs: NOW - 40 * DAY }],
    now: NOW,
    maxAgeDays: 30,
  });
  assert.deepEqual(plan.deleteOrphaned, ["stale.tar.gz"]);
  assert.deepEqual(plan.deleteExpired, []);
});

test("megaRetentionPlan defaults maxAgeDays to MEGA_OFFSITE_RETENTION_DAYS", () => {
  const justUnder = megaRetentionPlan({
    localNames: ["f"],
    remoteFiles: [{ name: "f", mtimeMs: NOW - (MEGA_OFFSITE_RETENTION_DAYS - 1) * DAY }],
    now: NOW,
  });
  assert.deepEqual(justUnder.keep, ["f"]);

  const justOver = megaRetentionPlan({
    localNames: ["f"],
    remoteFiles: [{ name: "f", mtimeMs: NOW - (MEGA_OFFSITE_RETENTION_DAYS + 1) * DAY }],
    now: NOW,
  });
  assert.deepEqual(justOver.deleteExpired, ["f"]);
});

test("megaRetentionPlan treats zero/negative maxAgeDays as expire-everything", () => {
  const plan = megaRetentionPlan({
    localNames: ["f"],
    remoteFiles: [{ name: "f", mtimeMs: NOW }],
    now: NOW,
    maxAgeDays: 0,
  });
  // mtimeMs === now => ageMs 0, not > 0, so still kept at the exact boundary.
  assert.deepEqual(plan.keep, ["f"]);

  const older = megaRetentionPlan({
    localNames: ["f"],
    remoteFiles: [{ name: "f", mtimeMs: NOW - 1 }],
    now: NOW,
    maxAgeDays: 0,
  });
  assert.deepEqual(older.deleteExpired, ["f"]);
});

test("megaRetentionPlan handles an empty remote listing", () => {
  const plan = megaRetentionPlan({ localNames: ["f"], remoteFiles: [], now: NOW });
  assert.deepEqual(plan, { keep: [], deleteOrphaned: [], deleteExpired: [] });
});

test("namesToDelete concatenates orphaned then expired", () => {
  const plan = megaRetentionPlan({
    localNames: [],
    remoteFiles: [
      { name: "orphan.gz", mtimeMs: NOW - 1 * DAY },
      { name: "expired.gz", mtimeMs: NOW - 1 * DAY },
    ],
    now: NOW,
  });
  // Force one into "expired" bucket by making it local but old.
  const mixed = megaRetentionPlan({
    localNames: ["expired.gz"],
    remoteFiles: [
      { name: "orphan.gz", mtimeMs: NOW - 1 * DAY },
      { name: "expired.gz", mtimeMs: NOW - 40 * DAY },
    ],
    now: NOW,
    maxAgeDays: 30,
  });
  assert.deepEqual(namesToDelete(mixed), ["orphan.gz", "expired.gz"]);
  assert.ok(plan.deleteOrphaned.includes("orphan.gz"));
});

#!/usr/bin/env -S npx tsx
/**
 * Thin CLI adapter around lib/offsite-retention.ts for scripts/backup-offsite.sh
 * (bash has no good story for the set-difference + "which rule applies" logic
 * that module owns, and duplicating it in awk would mean two copies to keep in
 * sync — see the module's own doc comment for the full rationale).
 *
 * Usage:
 *   tsx scripts/mega-prune-plan.ts <local-dir>  <  <newline-separated remote names on stdin>
 *
 * Prints one remote name per line that should be deleted from Mega, or nothing
 * if there's nothing to prune. Exits non-zero only on a usage error.
 *
 * Only wires up the MIRROR rule (delete remote names no longer present in
 * <local-dir>) — every remote entry is handed to `megaRetentionPlan` with
 * `mtimeMs = now`, so the age-cap rule (`deleteExpired`) can never fire here.
 * That rule is implemented and unit-tested in lib/offsite-retention.ts but
 * deliberately NOT wired live yet: doing so needs per-file remote timestamps
 * parsed out of `megals -l`, and that output format has not been verified
 * against a real Mega account (see backup-offsite.sh's MEGA section comment).
 * The mirror rule alone needs only remote *names*, which `megals` (no `-l`)
 * gives reliably, so it's safe to run unattended today.
 */
import { readFileSync, readdirSync } from "node:fs";
import { megaRetentionPlan } from "../lib/offsite-retention.ts";

function main(): void {
  const localDir = process.argv[2];
  if (!localDir) {
    console.error("usage: mega-prune-plan.ts <local-dir>  <  <remote names, one per line>");
    process.exit(2);
  }

  let localNames: string[];
  try {
    localNames = readdirSync(localDir).filter((n) => !n.endsWith(".partial"));
  } catch (e) {
    console.error(`mega-prune-plan: cannot read local dir ${localDir}: ${(e as Error).message}`);
    process.exit(2);
  }

  const stdin = readFileSync(0, "utf8");
  const remoteNames = stdin
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0);

  const now = Date.now();
  const plan = megaRetentionPlan({
    localNames,
    // mtimeMs = now for every entry so the age-cap rule can never fire here —
    // see the module doc comment above for why only the mirror rule is live.
    remoteFiles: remoteNames.map((name) => ({ name, mtimeMs: now })),
    now,
  });

  for (const name of plan.deleteOrphaned) console.log(name);
}

main();

